function update(dt){time+=dt;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show');}if(mode!=='playing')return;const p=player;p.anim+=dt;p.invuln=Math.max(0,p.invuln-dt);p.dashCooldown=Math.max(0,p.dashCooldown-dt);p.attack=Math.max(0,p.attack-dt);p.dash=Math.max(0,p.dash-dt);p.jumpBuffer=Math.max(0,p.jumpBuffer-dt);if(p.x>world.checkpoints[checkpoint]+180&&checkpoint<world.checkpoints.length-1)checkpoint++;
 const input=(keys.right?1:0)-(keys.left?1:0);if(input){p.facing=input;p.vx+=input*1500*dt;}else p.vx*=Math.pow(p.grounded?.0001:.82,dt*60);p.vx=clamp(p.vx,-280,280);if(p.dash>0)p.vx=p.facing*680;
 if(p.jumpBuffer>0&&(p.grounded||p.coyote>0)){p.vy=-560;p.grounded=false;p.coyote=0;p.jumpBuffer=0;sound('jump');burst(p.x+17,p.y+52,'#b9ff39',5);}p.vy+=1500*dt;p.vy=Math.min(p.vy,900);const oldY=p.y;p.x=clamp(p.x+p.vx*dt,0,world.length-30);p.y+=p.vy*dt;
 const ground=world.ground-p.h;if(p.y>=ground){p.y=ground;p.vy=0;p.grounded=true;p.coyote=.11}else{if(p.grounded)p.coyote=.11;else p.coyote=Math.max(0,p.coyote-dt);p.grounded=false;}
 for(const platform of world.platforms){if(p.x+p.w>platform.x&&p.x<platform.x+platform.w&&oldY+p.h<=platform.y+7&&p.y+p.h>=platform.y&&p.vy>=0){p.y=platform.y-p.h;p.vy=0;p.grounded=true;p.coyote=.11;}}
 for(const item of world.pickups){if(item.got)continue;const iy=item.y+Math.sin(time*3+item.phase)*5;if(Math.hypot((p.x+p.w/2)-item.x,(p.y+p.h/2)-iy)<34){item.got=true;shards++;score+=100;player.rage=Math.min(100,player.rage+11);burst(item.x,iy,'#c7ff49',10);sound('pickup');showToast('SYMBIOTE SHARD ABSORBED');}}
 for(const h of world.hazards){if(!h.alive)continue;const hx=h.x,hy=h.y;if(p.x+p.w-5>hx&&p.x+5<hx+h.w&&p.y+p.h>hy&&p.y<hy+h.h){if(p.dash>0){h.alive=false;score+=60;burst(h.x,h.y,'#b9ff39',10);}else hurt(h.type==='mine'?16:12);}}
 for(const d of world.drones){if(!d.alive)continue;d.phase+=dt;d.y=d.baseY+Math.sin(d.phase*2.2)*22;if(Math.abs(d.x-p.x)<36&&Math.abs(d.y-(p.y+25))<39){if(p.dash>0){d.alive=false;score+=180;burst(d.x,d.y,'#b9ff39',14);}else hurt(13);}}
 for(const b of world.particles){b.x+=b.vx*dt;b.y+=b.vy*dt;b.vy+=360*dt;b.life-=dt;}world.particles=world.particles.filter(b=>b.life>0);
 camera=clamp(p.x-W*.36,0,world.length-W);shake=Math.max(0,shake-dt*28);if(p.x>=world.length-170){score+=shards*250;showResult(true);}updateHud();
}
function rr(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);}
function drawBackground(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#071014');g.addColorStop(.55,'#132020');g.addColorStop(1,'#111a19');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 // distant storm glow
 const glow=ctx.createRadialGradient(W*.71,H*.36,2,W*.71,H*.36,H*.55);glow.addColorStop(0,'rgba(87,173,133,.18)');glow.addColorStop(1,'rgba(3,8,10,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);
 for(let layer=0;layer<3;layer++){const speed=[.12,.28,.48][layer],alpha=[.24,.4,.7][layer];for(const b of world.buildings){let x=(b.x-camera*speed)%(world.length+W);if(x< -220)x+=world.length+W;x-=camera*0;const top=H-b.h*(.66+layer*.18);ctx.fillStyle=layer===2?'#101b1a':layer===1?'#0c1719':'#0a1417';ctx.fillRect(x,top,b.w,b.h+H*.3);ctx.fillStyle=`rgba(103,173,139,${alpha*.18})`;ctx.fillRect(x,top,b.w,2);const cols=Math.floor(b.w/18);for(let c=0;c<cols;c++){for(let r=0;r<Math.floor(b.h/24);r++){if(((c*7+r*3+Math.floor(b.seed))%5)!==0){ctx.fillStyle=`rgba(182,238,167,${alpha*(.07+((c+r)%3)*.035)})`;ctx.fillRect(x+8+c*18,top+10+r*24,3,6);}}}}
 }
 // skyline sign + moon
 ctx.fillStyle='rgba(185,255,57,.16)';ctx.font='900 11px system-ui';ctx.letterSpacing='4px';ctx.fillText('K L I N T  T O W E R',W*.63-camera*.08,H*.22);
 const floor=world.ground;const fg=ctx.createLinearGradient(0,floor,0,H);fg.addColorStop(0,'#1a2522');fg.addColorStop(1,'#070b0d');ctx.fillStyle=fg;ctx.fillRect(0,floor,W,H-floor);ctx.strokeStyle='rgba(189,255,89,.35)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,floor);ctx.lineTo(W,floor);ctx.stroke();
 for(let i=0;i<18;i++){const x=((i*113-camera*.8)%(W+120)+W+120)%(W+120)-50;ctx.strokeStyle='rgba(130,192,153,.08)';ctx.beginPath();ctx.moveTo(x,floor+9);ctx.lineTo(x-25,floor+23);ctx.lineTo(x+50,floor+23);ctx.stroke();}
 for(const r of world.rain){r.y+=r.speed*(1/60);if(r.y>H){r.y=-20;r.x=rnd(0,W);}ctx.strokeStyle=`rgba(151,205,192,${r.alpha})`;ctx.lineWidth=.7;ctx.beginPath();ctx.moveTo(r.x,r.y);ctx.lineTo(r.x-5,r.y+r.len);ctx.stroke();}
}
function drawWorld(){ctx.save();ctx.translate(-camera,0);const floor=world.ground;
 // platforms
 for(const pl of world.platforms){ctx.fillStyle='#283631';ctx.fillRect(pl.x,pl.y,pl.w,pl.h);ctx.fillStyle='#b9ff39';ctx.globalAlpha=.5;ctx.fillRect(pl.x,pl.y,pl.w,2);ctx.globalAlpha=1;ctx.fillStyle='#0a1112';ctx.fillRect(pl.x+7,pl.y+pl.h,pl.w-14,6);}
 // hazards
 for(const h of world.hazards){if(!h.alive)continue;if(h.type==='spike'){ctx.fillStyle='#55734a';ctx.beginPath();for(let x=0;x<h.w;x+=16){ctx.moveTo(h.x+x,h.y+h.h);ctx.lineTo(h.x+x+8,h.y-5);ctx.lineTo(h.x+x+16,h.y+h.h);}ctx.fill();ctx.strokeStyle='#b9ff39';ctx.globalAlpha=.62;ctx.stroke();ctx.globalAlpha=1;}else{const pulse=.5+.5*Math.sin(time*8+h.x);ctx.fillStyle=`rgba(251,77,91,${.16+pulse*.22})`;ctx.beginPath();ctx.arc(h.x+h.w/2,h.y+h.h/2,18+pulse*5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#2d252a';ctx.beginPath();ctx.arc(h.x+h.w/2,h.y+h.h/2,10,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ff626d';ctx.beginPath();ctx.arc(h.x+h.w/2,h.y+h.h/2,3,0,Math.PI*2);ctx.fill();}}
 // shards
 for(const item of world.pickups){if(item.got)continue;const y=item.y+Math.sin(time*3+item.phase)*5;ctx.save();ctx.translate(item.x,y);ctx.rotate(time*1.6+item.phase);ctx.shadowColor='#c7ff49';ctx.shadowBlur=15;ctx.fillStyle='#d5ff64';ctx.beginPath();ctx.moveTo(0,-9);ctx.lineTo(7,0);ctx.lineTo(0,9);ctx.lineTo(-7,0);ctx.closePath();ctx.fill();ctx.restore();}
 // drones
 for(const d of world.drones){if(!d.alive)continue;ctx.save();ctx.translate(d.x,d.y);ctx.shadowColor='#fb5a64';ctx.shadowBlur=12;ctx.fillStyle='#202d2e';rr(-16,-11,32,22,6);ctx.fill();ctx.strokeStyle='#82908d';ctx.lineWidth=1;ctx.stroke();ctx.fillStyle='#ff6970';ctx.fillRect(-5,-2,10,4);ctx.shadowBlur=0;ctx.strokeStyle='#71827c';ctx.beginPath();ctx.moveTo(-20,-14);ctx.lineTo(-11,-9);ctx.moveTo(20,-14);ctx.lineTo(11,-9);ctx.stroke();ctx.restore();}
 // extraction beacon
 const bx=world.length-130;ctx.fillStyle='rgba(185,255,57,.08)';ctx.fillRect(bx-25,0,50,floor);ctx.strokeStyle='#b9ff39';ctx.globalAlpha=.5+.35*Math.sin(time*4);ctx.beginPath();ctx.moveTo(bx,floor);ctx.lineTo(bx,25);ctx.stroke();ctx.globalAlpha=1;ctx.fillStyle='#d9ff7c';ctx.font='800 9px system-ui';ctx.textAlign='center';ctx.fillText('EXTRACTION',bx,floor-28);ctx.textAlign='left';
 for(const b of world.particles){ctx.globalAlpha=clamp(b.life/b.max,0,1);ctx.fillStyle=b.color;ctx.shadowColor=b.color;ctx.shadowBlur=10;ctx.beginPath();ctx.arc(b.x,b.y,b.size,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;ctx.shadowBlur=0;
 drawPlayer();ctx.restore();}

