 const wiggle=Math.sin(time*10+p.x*.03)*5;ctx.strokeStyle='#080d0d';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-8,-12);ctx.quadraticCurveTo(-23,-24+wiggle,-25,-33+wiggle);ctx.moveTo(8,-13);ctx.quadraticCurveTo(20,-26-wiggle,29,-23-wiggle);ctx.stroke();ctx.strokeStyle='#53605a';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-8,-12);ctx.quadraticCurveTo(-23,-24+wiggle,-25,-33+wiggle);ctx.moveTo(8,-13);ctx.quadraticCurveTo(20,-26-wiggle,29,-23-wiggle);ctx.stroke();
