function showToast(s){ui.toast.textContent=s;ui.toast.classList.add('show');toastTimer=1.35;}
function panelMenu(){ui.panel.innerHTML=`<div class="eyebrow">CLASSIFIED // PROJECT VENOM</div><h1>CITY OF <span>TEETH.</span></h1><p class="panel-copy">The lab is burning. The hunters are closing in. Take back the night and make it to the extraction beacon.</p><div class="feature-row"><div class="feature"><b>ABSORB</b><span>Collect 8 shards</span></div><div class="feature"><b>RIP & TEAR</b><span>Strike with tendrils</span></div><div class="feature"><b>GET OUT</b><span>Reach the beacon</span></div></div><button class="primary" id="startBtn">ENTER THE NIGHT&nbsp; →</button><div class="fineprint">A / D OR ← / → MOVE &nbsp;·&nbsp; SPACE JUMP &nbsp;·&nbsp; J STRIKE &nbsp;·&nbsp; SHIFT RUSH</div>`;ui.overlay.classList.remove('hidden');document.getElementById('startBtn').onclick=startGame;}
